    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 12px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin: 0 0 0.5rem;
    color: #1f2937;
}

.modal-dialog p {
    margin: 0 0 1rem;
    font-size: 0.875rem;
    color: #6b7280;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
