.appearance-preview .preview-header {
    padding: 0.75rem 1rem;
    font-weight: 600;
    font-size: 0.875rem;
    border-bottom: 1px solid #e5e7eb;
}

.appearance-preview .preview-body {
    padding: 1rem;
}

.appearance-preview .preview-body p {
    margin: 0 0 0.5rem;
}

.appearance-preview .preview-secondary {
    opacity: 0.6;
}

.appearance-preview .preview-button {
    padding: 0.375rem 0.75rem;
    border-radius: 4px;
    border: none;
    cursor: pointer;
    font-size: 0.8rem;
    font-weight: 500;
    margin-top: 0.5rem;
}

/* Theme variants */
.appearance-preview.light {
    background: #ffffff;
    color: #1f2937;
}

.appearance-preview.light .preview-header {
    background: #f9fafb;
}

.appearance-preview.light .preview-button {
    background: #2563eb;
    color: #fff;
}

.appearance-preview.dark {
    background: #1f2937;
    color: #f9fafb;
    border-color: #374151;
}

.appearance-preview.dark .preview-header {
    background: #111827;
    border-color: #374151;
}

.appearance-preview.dark .preview-button {
    background: #3b82f6;
    color: #fff;
}

.appearance-preview.system {
    background: #f0f9ff;
    color: #1e3a5f;
    border-color: #bae6fd;
}

.appearance-preview.system .preview-header {
    background: #e0f2fe;
    border-color: #bae6fd;
}

.appearance-preview.system .preview-button {
    background: #0284c7;
    color: #fff;
}

/* Font size variants */
.appearance-preview.small {
    font-size: 0.75rem;
}

.appearance-preview.medium {
    font-size: 0.875rem;
}

.appearance-preview.large {
    font-size: 1.05rem;
}

/* Compact mode */
.appearance-preview.compact .preview-header {
    padding: 0.375rem 0.75rem;
}

.appearance-preview.compact .preview-body {
    padding: 0.5rem 0.75rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-size: 0.875rem;
    font-weight: 500;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.15);
    z-index: 2000;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #ecfdf5;
    color: #065f46;
    border: 1px solid #a7f3d0;
}

.toast.error {
    background: #fef2f2;
    color: #991b1b;
    border: 1px solid #fecaca;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.875rem;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    color: #6b7280;
    font-size: 1rem;
}
